(2, 3);

DROP TABLE IF EXISTS `agriculteur`;
CREATE TABLE `agriculteur` (
  `id` int(11) NOT NULL,
  `utilisateur_id` int(11) NOT NULL,
  `adresse` varchar(255) DEFAULT NULL,
  `superficie_terre` double DEFAULT NULL,
  `type_culture` varchar(100) DEFAULT NULL,
  `experience_annees` int(11) DEFAULT NULL,
  `statuscompte` varchar(20) DEFAULT 'en_attente',
  `compteverifie` tinyint(1) DEFAULT 0,
  `date_verification` datetime DEFAULT NULL,
  `motif_rejet` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

