('Subvention Verte', 'Subvention', 0.0, 3000, 20000, 'Projet ecologique obligatoire');

DROP TABLE IF EXISTS `offre_financiere`;
CREATE TABLE `offre_financiere` (
    `id_offre` int(11) NOT NULL AUTO_INCREMENT,
    `nom_offre` varchar(100) NOT NULL,
    `conditions` text,
    `statut` varchar(30),
    `id_produit` int(11) NOT NULL,
    PRIMARY KEY (`id_offre`),
    CONSTRAINT `fk_produit` FOREIGN KEY (`id_produit`) REFERENCES `produit_financier`(`id_produit`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

