-- =============================================
-- TRIGGERS
-- =============================================

DELIMITER $$
CREATE TRIGGER `after_piece_jointe_delete` AFTER DELETE ON `piecejointe` FOR EACH ROW BEGIN
    DECLARE nb INT;
    SELECT COUNT(*) INTO nb FROM piecejointe WHERE message_id = OLD.message_id;
    UPDATE message
    SET a_piece_jointe = IF(nb > 0, TRUE, FALSE),
        nb_pieces_jointes = nb
    WHERE id = OLD.message_id;
END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER `after_piece_jointe_insert` AFTER INSERT ON `piecejointe` FOR EACH ROW BEGIN
    UPDATE message
    SET a_piece_jointe = TRUE,
        nb_pieces_jointes = (SELECT COUNT(*) FROM piecejointe WHERE message_id = NEW.message_id)
    WHERE id = NEW.message_id;
END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER `sync_project_status_on_insert` AFTER INSERT ON `decisionfinanciere` FOR EACH ROW BEGIN
  UPDATE projectagricole
  SET statut = CASE
    WHEN NEW.statut = 'Approuve' THEN 'accepte'
    WHEN NEW.statut = 'Rejete'   THEN 'refuse'
    ELSE 'en cours'
  END
  WHERE idproject = (
    SELECT idProjet FROM evaluationrisque WHERE idEvaluation = NEW.idEvaluation
  );
END$$
DELIMITER ;

DELIMITER $$
CREATE TRIGGER `sync_project_status_on_update` AFTER UPDATE ON `decisionfinanciere` FOR EACH ROW BEGIN
  UPDATE projectagricole
  SET statut = CASE
    WHEN NEW.statut = 'Approuve' THEN 'accepte'
    WHEN NEW.statut = 'Rejete'   THEN 'refuse'
    ELSE 'en cours'
  END
  WHERE idproject = (
    SELECT idProjet FROM evaluationrisque WHERE idEvaluation = NEW.idEvaluation
  );
END$$
DELIMITER ;


-- =============================================
-- VUES (Views)
-- =============================================

CREATE OR REPLACE VIEW `v_dernier_message_conversation` AS
SELECT `c`.`id` AS `conversation_id`, `m`.`id` AS `message_id`, `m`.`contenu` AS `contenu`,
       `m`.`date_envoi` AS `date_envoi`, `m`.`expediteur_id` AS `expediteur_id`, `m`.`est_lu` AS `est_lu`
FROM (`conversation` `c` LEFT JOIN `message` `m`
  ON (`m`.`id` = (SELECT MAX(`message`.`id`) FROM `message` WHERE `message`.`conversation_id` = `c`.`id` AND `message`.`est_supprime` = 0)));

CREATE OR REPLACE VIEW `v_messages_avec_pieces_jointes` AS
SELECT `m`.`id` AS `message_id`, `m`.`conversation_id`, `m`.`expediteur_id`, `m`.`contenu`,
       `m`.`date_envoi`, `m`.`a_piece_jointe`, `m`.`nb_pieces_jointes`,
       COUNT(`p`.`id`) AS `total_fichiers`,
       SUM(CASE WHEN `p`.`type_fichier` = 'image' THEN 1 ELSE 0 END) AS `nb_images`,
       SUM(CASE WHEN `p`.`type_fichier` = 'document' THEN 1 ELSE 0 END) AS `nb_documents`,
       SUM(CASE WHEN `p`.`type_fichier` = 'audio' THEN 1 ELSE 0 END) AS `nb_audios`,
       SUM(`p`.`taille_octets`) AS `taille_totale`
FROM (`message` `m` LEFT JOIN `piecejointe` `p` ON (`m`.`id` = `p`.`message_id`))
GROUP BY `m`.`id`, `m`.`conversation_id`, `m`.`expediteur_id`, `m`.`contenu`, `m`.`date_envoi`, `m`.`a_piece_jointe`, `m`.`nb_pieces_jointes`;

CREATE OR REPLACE VIEW `v_messages_non_lus` AS
SELECT `c`.`utilisateur1_id` AS `utilisateur_id`, `c`.`utilisateur2_id` AS `correspondant_id`, COUNT(0) AS `nb_non_lus`
FROM (`conversation` `c` JOIN `message` `m` ON (`m`.`conversation_id` = `c`.`id`))
WHERE `m`.`expediteur_id` = `c`.`utilisateur2_id` AND `m`.`est_lu` = 0 AND `m`.`est_supprime` = 0
GROUP BY `c`.`utilisateur1_id`, `c`.`utilisateur2_id`
UNION ALL
SELECT `c`.`utilisateur2_id`, `c`.`utilisateur1_id`, COUNT(0)
FROM (`conversation` `c` JOIN `message` `m` ON (`m`.`conversation_id` = `c`.`id`))
WHERE `m`.`expediteur_id` = `c`.`utilisateur1_id` AND `m`.`est_lu` = 0 AND `m`.`est_supprime` = 0
GROUP BY `c`.`utilisateur2_id`, `c`.`utilisateur1_id`;

CREATE OR REPLACE VIEW `v_stats_fichiers_conversation` AS
SELECT `c`.`id` AS `conversation_id`,
       COUNT(DISTINCT `p`.`id`) AS `total_fichiers`,
       SUM(CASE WHEN `p`.`type_fichier` = 'image' THEN 1 ELSE 0 END) AS `total_images`,
       SUM(CASE WHEN `p`.`type_fichier` = 'audio' THEN 1 ELSE 0 END) AS `total_audios`,
       SUM(CASE WHEN `p`.`type_fichier` = 'document' THEN 1 ELSE 0 END) AS `total_documents`,
       SUM(`p`.`taille_octets`) AS `espace_utilise`
FROM ((`conversation` `c` LEFT JOIN `message` `m` ON (`c`.`id` = `m`.`conversation_id`))
      LEFT JOIN `piecejointe` `p` ON (`m`.`id` = `p`.`message_id`))
GROUP BY `c`.`id`;

CREATE OR REPLACE VIEW `v_stats_securite_utilisateur` AS
SELECT `u`.`id`, `u`.`email`,
       `p`.`est_active` AS `a2fa_active`, `p`.`methode_preferee` AS `methode_2fa`,
       COUNT(DISTINCT `h`.`id`) AS `nb_connexions_total`,
       SUM(CASE WHEN `h`.`connexion_reussie` = 1 THEN 1 ELSE 0 END) AS `nb_connexions_reussies`,
       SUM(CASE WHEN `h`.`connexion_reussie` = 0 THEN 1 ELSE 0 END) AS `nb_tentatives_echouees`,
       MAX(`h`.`date_connexion`) AS `derniere_connexion`
FROM ((`utilisateur` `u` LEFT JOIN `parametres2fa` `p` ON (`u`.`id` = `p`.`utilisateur_id`))
      LEFT JOIN `historiqueconnexion` `h` ON (`u`.`id` = `h`.`utilisateur_id`))
GROUP BY `u`.`id`, `u`.`email`, `p`.`est_active`, `p`.`methode_preferee`;


-- =============================================
-- EVENEMENTS (Events)
-- =============================================

DELIMITER $$
CREATE EVENT IF NOT EXISTS `nettoyer_codes_2fa_expires`
ON SCHEDULE EVERY 1 HOUR
STARTS CURRENT_TIMESTAMP
ON COMPLETION NOT PRESERVE ENABLE
DO DELETE FROM code2fa WHERE date_expiration < NOW() AND est_utilise = FALSE$$
DELIMITER ;


